SP=/tmp/claude-0/-home-user-ainews/ff2c21c3-96c1-5fd6-ac6a-948c6d24d179/scratchpad && cat > $SP/filed.js <<'EOF'
const fs=require('fs');
const counts={};
for(const f of fs.readdirSync('data').filter(x=>/^\d{4}-\d\d-\d\d\.json$/.test(x)).sort()){
  const d=f.slice(0,10); if(d<'2026-09-28') continue;
  const j=JSON.parse(fs.readFileSync('data/'+f,'utf8'));
  for(const s of j.sections||[]) for(const it of s.items||[]) for(const sl of it.storylines||[]){
    counts[sl]=counts[sl]||{}; counts[sl][d]=(counts[sl][d]||0)+1;
  }
}
for(const sl of Object.keys(counts).sort()){
  const ds=Object.keys(counts[sl]).sort();
  console.log(sl.padEnd(34)+' last='+ds[ds.length-1]+'  thisweek='+ds.filter(d=>d>='2026-10-26'&&d<='2026-11-01').length+'  dates='+ds.join(' '));
}
EOF
node $SP/filed.js
echo "--- storyline last state dates + status ---"
for f in storylines/*.json; do node -e "const j=require('/home/user/ainews/$f');const s=j.states||[];console.log(j.id.padEnd(34)+j.status.padEnd(10)+'laststate='+(s.length?s[s.length-1].date:'none')+' nstates='+s.length+' nfigs='+(j.figures||[]).length+' nq='+(j.questions||[]).length);"; done

